-- Определите, сколько н пишется на месте пропуска, и установите соответствие между столбц...
INSERT INTO questions (title, type, "order", lesson_id, subject_id, correct_answer, explanation)
VALUES ('Определите, сколько н пишется на месте пропуска, и установите соответствие между столбцами таблицы:

А) Семейство, в котором он родился, было многочисле..о.

Б) Торжестве..о на землю сходит ночь.

В) Издание богато иллюстрирова..о цветными фотографиями.

Г) В результате проверки было выявле..о много нарушений.

1) Одна буква н пишется в краткой форме страдательного причастия.

2) Одна буква н пишется в наречии, образованном от прилагательного с одной буквой н.

3) Две буквы н пишутся в наречии, образованном от прилагательного (или причастия) с двумя буквами н.

4) Две буквы н пишутся в краткой форме прилагательного, полная форма которого пишется с двумя буквами н.

5) Одна буква н пишется в краткой форме прилагательного, полная форма которого пишется с одной буквой н.

Ответ запишите в виде сочетания букв и цифр, соблюдая алфавитную последовательность букв левого столбца. Например: А1Б1В4Г2.', 'INPUT'::question_type, 60, 8, NULL, 'А4Б3В1Г1', NULL);

