    ('винт..к, на прошедш..й неделе', FALSE),
    ('зимн..м днём, протал..нка', TRUE),
    ('обидч..вый, дождич..к', FALSE)
) AS v(text, is_correct);

-- Найдите в предложениях слово с орфографической ошибкой и запишите его в исправленном ви...
INSERT INTO questions (title, type, "order", lesson_id, subject_id, correct_answer, explanation)
VALUES ('Найдите в предложениях слово с орфографической ошибкой и запишите его в исправленном виде (в той форме, в которой оно употреблено).

Аптекарь жил в своём доме, на первом этаже которого размещалась аптека. Всё её убранство было довольно скромное, но прочное, явно носящее аптекарьский характер: в нескольких витринах пестрели высушенные лекарственные растения, на подоконниках лежали стеклянные трубочки, а на столе стояли спиртовые лампы.', 'INPUT'::question_type, 70, 8, NULL, 'аптекарский', NULL);

-- В приведённом ниже предложении допущена орфографическая ошибка. Найдите слово с ошибкой...
INSERT INTO questions (title, type, "order", lesson_id, subject_id, correct_answer, explanation)
VALUES ('В приведённом ниже предложении допущена орфографическая ошибка. Найдите слово с ошибкой и запишите его в исправленном виде (в той форме, в которой оно употреблено в тексте).

Мировые информационные агентства сообщили об ужасном урагане, который стал причиной происшествия в окресностях французского городка.', 'INPUT'::question_type, 71, 8, NULL, 'окрестностях|вокрестностях', NULL);

-- В приведённом ниже предложении допущена орфографическая ошибка. Найдите слово с ошибкой...
